recipes.code:
{
  "inputs": [
    {
      "id": "tokonomix-api-key",
      "type": "promptString",
      "description": "Tokonomix API key (tok_live_...). Optional - keyless onboarding works without it.",
      "password": true
    }
  ],
  "servers": {
    "council": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "tokonomix-council-mcp@1.11.0"
      ],
      "env": {
        "TOKONOMIX_API_KEY": "${input:tokonomix-api-key}"
      }
    }
  }
}
